#!/usr/bin/env python3
"""Offline DNS model-based regression workbench.

Reads a single UTF-8 JSON document on standard input (synthetic authoritative
zone data plus explicit experiment policies), validates it against the frozen
local contract, models a deliberately simplified resolver for every
query/profile combination, adjudicates supplied observations against that
model, and selects an exact minimum-cost diagnostic basis.

A rejectable document produces exactly ``{"error":"invalid-input"}`` on
standard output; a valid document produces exactly the fields ``runs``,
``audits`` and ``diagnostic``.  Either way the exit status is zero.

No network, resolver, or non-standard-library dependency is used.
"""

from array import array
from itertools import accumulate
import ipaddress
import json
import re
import sys

# ---------------------------------------------------------------- constants

INPUT_LIMIT = 8 * 1024 * 1024          # 8 MiB, counted in bytes
MAX_DEPTH = 32                         # nested object/array containers
MAX_ZONES = 16
MAX_ZONE_RECORDS = 1024
MAX_RRSET_RECORDS = 64
MAX_PROFILES = 8
MAX_QUERIES = 20
MAX_OBSERVATIONS = 64
MAX_ANSWER_RECORDS = 128
MAX_ALIASES = 64
MAX_COST = 1000
MAX_ID = 32
MAX_LABEL = 63
MAX_NAME_WIRE = 255
MAX_TXT = 256

TYPES = ('A', 'AAAA', 'TXT', 'CNAME')
RCODES = ('NOERROR', 'NXDOMAIN', 'SERVFAIL', 'REFUSED')
CNAME_MODES = ('follow', 'stop')
WILDCARD_MODES = ('rfc', 'off', 'one-label')

_ASCII_LABEL = frozenset(
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-')
_ID_CHARS = _ASCII_LABEL

_ERROR = '{"error":"invalid-input"}\n'


class Invalid(Exception):
    """Raised for every condition that makes the document rejectable."""


# --------------------------------------------------------------- scanning --

_STRING_RE = re.compile(rb'"(?:[^"\\]|\\.)*"')

_depth_table = bytearray(256)
_depth_table[0x5B] = 1      # '['
_depth_table[0x7B] = 1      # '{'
_depth_table[0x5D] = 0xFF   # ']'
_depth_table[0x7D] = 0xFF   # '}'
_DEPTH_TABLE = bytes(_depth_table)


def nesting_within_limit(raw):
    """True when no object/array nesting exceeds MAX_DEPTH containers.

    String literals are removed first (at byte level; UTF-8 continuation
    bytes can never collide with the ASCII delimiters) so that bracket
    characters inside strings are ignored.  The remaining bytes are mapped to
    +1/-1 and folded with :func:`itertools.accumulate`, which runs at C speed.
    """
    stripped = _STRING_RE.sub(b'', raw)
    depth = 0
    size = len(stripped)
    step = 1 << 16
    for start in range(0, size, step):
        chunk = stripped[start:start + step].translate(_DEPTH_TABLE)
        if not chunk:
            continue
        running = list(accumulate(array('b', chunk), initial=depth))
        if max(running) > MAX_DEPTH:
            return False
        depth = running[-1]
    return True


def _hook_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid('duplicate object key')
        result[key] = value
    return result


def _hook_constant(_name):
    raise Invalid('nonfinite number')


def _hook_float(text):
    value = float(text)
    if value != value or value in (_INF, -_INF):
        raise Invalid('nonfinite number')
    return value


_INF = float('inf')


def load_document(raw):
    """Parse and shallow-validate the raw stdin bytes."""
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('malformed utf-8')
    if not nesting_within_limit(raw):
        raise Invalid('nesting depth')
    try:
        document = json.loads(
            text,
            object_pairs_hook=_hook_pairs,
            parse_constant=_hook_constant,
            parse_float=_hook_float,
        )
    except Invalid:
        raise
    except Exception:
        raise Invalid('malformed json')
    if type(document) is not dict:
        raise Invalid('root object')
    return document


# ------------------------------------------------------------ name checks --

def exact_keys(value, keys):
    if type(value) is not dict:
        raise Invalid('object type')
    if len(value) != len(keys):
        raise Invalid('object keys')
    for key in keys:
        if key not in value:
            raise Invalid('object keys')
    return value


def canon_name(value):
    """Validate an absolute name and return its canonical (lowercase) form."""
    if type(value) is not str:
        raise Invalid('name type')
    if not value:
        raise Invalid('name empty')
    if value == '.':
        return '.'
    if not value.endswith('.'):
        raise Invalid('relative name')
    wire = 1
    for label in value[:-1].split('.'):
        size = len(label)
        if size == 0 or size > MAX_LABEL:
            raise Invalid('label size')
        if label != '*':
            for char in label:
                if char not in _ASCII_LABEL:
                    raise Invalid('label character')
        wire += size + 1
        if wire > MAX_NAME_WIRE:
            raise Invalid('name wire length')
    return value.lower()


def is_at_or_below(name, origin):
    """Whole-label suffix test; the root contains every name."""
    if origin == '.':
        return True
    if name == '.':
        return False
    return name == origin or name.endswith('.' + origin)


def label_count(name):
    if name == '.':
        return 0
    return name[:-1].count('.') + 1


def parent_name(name):
    if name == '.':
        return '.'
    return name[name.index('.') + 1:]


# ------------------------------------------------------------ data checks --

def canon_a_data(value):
    if type(value) is not str:
        raise Invalid('A data type')
    parts = value.split('.')
    if len(parts) != 4:
        raise Invalid('A data shape')
    for part in parts:
        if not part:
            raise Invalid('A data octet')
        if part[0] == '0' and len(part) > 1:
            raise Invalid('A data leading zero')
        for char in part:
            if char < '0' or char > '9':
                raise Invalid('A data digit')
        if int(part) > 255:
            raise Invalid('A data range')
    return value


def canon_aaaa_data(value):
    if type(value) is not str:
        raise Invalid('AAAA data type')
    if '%' in value:
        raise Invalid('AAAA scope')
    try:
        address = ipaddress.IPv6Address(value)
    except Exception:
        raise Invalid('AAAA data')
    return address.compressed


def canon_txt_data(value):
    if type(value) is not str:
        raise Invalid('TXT data type')
    if len(value) > MAX_TXT:
        raise Invalid('TXT length')
    for char in value:
        code = ord(char)
        if code < 0x20 or code > 0x7E:
            raise Invalid('TXT character')
    return value


def canon_record(value):
    exact_keys(value, ('owner', 'type', 'data'))
    owner = canon_name(value['owner'])
    rtype = value['type']
    if type(rtype) is not str or rtype not in TYPES:
        raise Invalid('record type')
    data = value['data']
    if rtype == 'A':
        rdata = canon_a_data(data)
    elif rtype == 'AAAA':
        rdata = canon_aaaa_data(data)
    elif rtype == 'TXT':
        rdata = canon_txt_data(data)
    else:
        rdata = canon_name(data)
    return owner, rtype, rdata


def check_id(value):
    if type(value) is not str:
        raise Invalid('id type')
    size = len(value)
    if size < 1 or size > MAX_ID:
        raise Invalid('id length')
    for char in value:
        if char not in _ID_CHARS:
            raise Invalid('id character')
    return value


# ------------------------------------------------------------ model types --

class Zone:
    __slots__ = ('origin', 'nlabels', 'rrsets', 'existing')

    def __init__(self, origin, rrsets):
        self.origin = origin
        self.nlabels = label_count(origin)
        self.rrsets = rrsets
        existing = {origin}
        for owner in rrsets:
            name = owner
            while name != origin:
                existing.add(name)
                name = parent_name(name)
        self.existing = existing

    def matches(self, name):
        return is_at_or_below(name, self.origin)

    def closest_encloser(self, name):
        existing = self.existing
        current = name
        while True:
            current = parent_name(current)
            if current in existing:
                return current
            if current == '.':
                return None

    def wildcard_of(self, encloser):
        return '*.' if encloser == '.' else '*.' + encloser


class Profile:
    __slots__ = ('id', 'max_aliases', 'cname', 'wildcard')

    def __init__(self, pid, max_aliases, cname, wildcard):
        self.id = pid
        self.max_aliases = max_aliases
        self.cname = cname
        self.wildcard = wildcard


class Query:
    __slots__ = ('id', 'name', 'type', 'cost')

    def __init__(self, qid, name, rtype, cost):
        self.id = qid
        self.name = name
        self.type = rtype
        self.cost = cost


class Observation:
    __slots__ = ('id', 'query', 'profile', 'timeout', 'rcode', 'records')

    def __init__(self, oid, query, profile, timeout, rcode, records):
        self.id = oid
        self.query = query
        self.profile = profile
        self.timeout = timeout
        self.rcode = rcode
        self.records = records


# ------------------------------------------------------------- validation --

def parse_zones(raw_zones):
    if type(raw_zones) is not list:
        raise Invalid('zones type')
    if len(raw_zones) > MAX_ZONES:
        raise Invalid('zone count')
    zones = {}
    total = 0
    for raw in raw_zones:
        exact_keys(raw, ('origin', 'records'))
        origin = canon_name(raw['origin'])
        if origin in zones:
            raise Invalid('conflicting zones')
        records = raw['records']
        if type(records) is not list:
            raise Invalid('zone records type')
        total += len(records)
        if total > MAX_ZONE_RECORDS:
            raise Invalid('zone record budget')
        rrsets = {}
        for raw_record in records:
            owner, rtype, rdata = canon_record(raw_record)
            if not is_at_or_below(owner, origin):
                raise Invalid('owner outside zone')
            if rtype == 'CNAME' and owner == origin:
                raise Invalid('cname at zone origin')
            by_type = rrsets.get(owner)
            if by_type is None:
                by_type = {}
                rrsets[owner] = by_type
            present = by_type.get(rtype)
            if present is None:
                by_type[rtype] = (rdata,)
            elif rdata not in present:
                if len(present) + 1 > MAX_RRSET_RECORDS:
                    raise Invalid('rrset size')
                by_type[rtype] = present + (rdata,)
        for owner, by_type in rrsets.items():
            if 'CNAME' in by_type:
                if len(by_type) > 1:
                    raise Invalid('cname coexistence')
                if len(by_type['CNAME']) != 1:
                    raise Invalid('cname targets')
        for rtype in by_type:
            by_type[rtype] = tuple(sorted(by_type[rtype]))
        zones[origin] = Zone(origin, rrsets)
    return zones


def parse_profiles(raw_profiles):
    if type(raw_profiles) is not list:
        raise Invalid('profiles type')
    if len(raw_profiles) < 1 or len(raw_profiles) > MAX_PROFILES:
        raise Invalid('profile count')
    profiles = {}
    for raw in raw_profiles:
        exact_keys(raw, ('id', 'max_aliases', 'cname', 'wildcard'))
        pid = check_id(raw['id'])
        if pid in profiles:
            raise Invalid('duplicate profile id')
        max_aliases = raw['max_aliases']
        if type(max_aliases) is not int:
            raise Invalid('max_aliases type')
        if max_aliases < 0 or max_aliases > MAX_ALIASES:
            raise Invalid('max_aliases range')
        cname = raw['cname']
        if type(cname) is not str or cname not in CNAME_MODES:
            raise Invalid('cname policy')
        wildcard = raw['wildcard']
        if type(wildcard) is not str or wildcard not in WILDCARD_MODES:
            raise Invalid('wildcard policy')
        profiles[pid] = Profile(pid, max_aliases, cname, wildcard)
    return profiles


def parse_queries(raw_queries):
    if type(raw_queries) is not list:
        raise Invalid('queries type')
    if len(raw_queries) > MAX_QUERIES:
        raise Invalid('query count')
    queries = {}
    for raw in raw_queries:
        exact_keys(raw, ('id', 'name', 'type', 'cost'))
        qid = check_id(raw['id'])
        if qid in queries:
            raise Invalid('duplicate query id')
        name = canon_name(raw['name'])
        rtype = raw['type']
        if type(rtype) is not str or rtype not in TYPES:
            raise Invalid('query type')
        cost = raw['cost']
        if type(cost) is not int:
            raise Invalid('cost type')
        if cost < 1 or cost > MAX_COST:
            raise Invalid('cost range')
        queries[qid] = Query(qid, name, rtype, cost)
    return queries


def parse_observations(raw_observations, queries, profiles):
    if type(raw_observations) is not list:
        raise Invalid('observations type')
    if len(raw_observations) > MAX_OBSERVATIONS:
        raise Invalid('observation count')
    observations = {}
    for raw in raw_observations:
        exact_keys(raw, ('id', 'query', 'profile', 'result'))
        oid = check_id(raw['id'])
        if oid in observations:
            raise Invalid('duplicate observation id')
        query_ref = raw['query']
        if type(query_ref) is not str or query_ref not in queries:
            raise Invalid('observation query reference')
        profile_ref = raw['profile']
        if type(profile_ref) is not str or profile_ref not in profiles:
            raise Invalid('observation profile reference')
        result = raw['result']
        exact_keys(result, ('status',))
        timeout = True
        rcode = None
        records = ()
        if result['status'] == 'timeout':
            pass
        else:
            exact_keys(result, ('status', 'rcode', 'answer'))
            if result['status'] != 'response':
                raise Invalid('result status')
            rcode = result['rcode']
            if type(rcode) is not str or rcode not in RCODES:
                raise Invalid('rcode')
            answer = result['answer']
            if type(answer) is not list:
                raise Invalid('answer type')
            if len(answer) > MAX_ANSWER_RECORDS:
                raise Invalid('answer size')
            records = tuple(canon_record(item) for item in answer)
            timeout = False
        observations[oid] = Observation(
            oid, query_ref, profile_ref, timeout, rcode, records)
    return observations


# ------------------------------------------------------------ the resolver --

def select_zone(zone_list, name):
    """Most specific matching zone: the matching origin with most labels."""
    for zone in zone_list:
        if is_at_or_below(name, zone.origin):
            return zone
    return None


def resolve(query, profile, zone_list):
    """Run the frozen local resolution loop for one query/profile pair."""
    current = query.name
    qtype = query.type
    wildcard = profile.wildcard
    stop = profile.cname == 'stop'
    max_aliases = profile.max_aliases
    seen = set()
    trace = []
    answer = []
    followed = 0
    while True:
        # 1. loop detection precedes every other check
        trace.append(current)
        if current in seen:
            return 'SERVFAIL', 'LOOP', current, answer, trace
        seen.add(current)
        # 2. authority
        zone = select_zone(zone_list, current)
        if zone is None:
            if followed == 0:
                return 'REFUSED', 'OUTSIDE', current, answer, trace
            return 'NOERROR', 'EXTERNAL', current, answer, trace
        # 3. source selection
        if current in zone.existing:
            source = current
        else:
            source = None
            if wildcard != 'off':
                encloser = zone.closest_encloser(current)
                if encloser is not None:
                    if (wildcard == 'rfc' or
                            label_count(current) == label_count(encloser) + 1):
                        candidate = zone.wildcard_of(encloser)
                        if candidate in zone.existing:
                            source = candidate
        if source is None:
            return 'NXDOMAIN', 'NXDOMAIN', current, answer, trace
        by_type = zone.rrsets.get(source)
        if not by_type:
            by_type = ()
        # 4. CNAME query types are answered directly
        if qtype == 'CNAME':
            targets = by_type.get('CNAME') if by_type else None
            if targets:
                for data in targets:
                    answer.append((current, 'CNAME', data))
                return 'NOERROR', 'ANSWER', current, answer, trace
            return 'NOERROR', 'NODATA', current, answer, trace
        # 5. alias policy for other query types
        targets = by_type.get('CNAME') if by_type else None
        if targets:
            target = targets[0]
            if stop:
                answer.append((current, 'CNAME', target))
                return 'NOERROR', 'CNAME_STOP', current, answer, trace
            if followed == max_aliases:
                return 'SERVFAIL', 'LIMIT', current, answer, trace
            answer.append((current, 'CNAME', target))
            followed += 1
            current = target
            continue
        # 6. requested RRset
        found = by_type.get(qtype) if by_type else None
        if found:
            for data in found:
                answer.append((current, qtype, data))
            return 'NOERROR', 'ANSWER', current, answer, trace
        return 'NOERROR', 'NODATA', current, answer, trace


# --------------------------------------------------------------- analysis --

def analyze(document):
    if set(document.keys()) != {'zones', 'profiles', 'queries', 'observations'}:
        raise Invalid('root keys')
    zones = parse_zones(document['zones'])
    profiles = parse_profiles(document['profiles'])
    queries = parse_queries(document['queries'])
    observations = parse_observations(
        document['observations'], queries, profiles)

    zone_list = sorted(
        zones.values(), key=lambda zone: (-zone.nlabels, zone.origin))
    profile_ids = sorted(profiles)
    query_ids = sorted(queries)

    run_index = {}
    runs = []
    for qid in query_ids:
        query = queries[qid]
        for pid in profile_ids:
            rcode, termination, final_name, answer, trace = resolve(
                query, profiles[pid], zone_list)
            run_index[(qid, pid)] = (rcode, answer)
            runs.append({
                'query': qid,
                'profile': pid,
                'rcode': rcode,
                'termination': termination,
                'final_name': final_name,
                'answer': [{'owner': owner, 'type': rtype, 'data': data}
                           for owner, rtype, data in answer],
                'trace': trace,
            })

    projection = {key: (rcode, frozenset(answer))
                  for key, (rcode, answer) in run_index.items()}

    audits = []
    for oid in sorted(observations):
        observation = observations[oid]
        if observation.timeout:
            audits.append({'id': oid, 'verdict': 'unobserved', 'different': []})
            continue
        rcode, answer = projection[(observation.query, observation.profile)]
        different = []
        if observation.rcode != rcode:
            different.append('rcode')
        if frozenset(observation.records) != answer:
            different.append('answer')
        audits.append({
            'id': oid,
            'verdict': 'divergence' if different else 'match',
            'different': different,
        })

    equivalence, basis, cost, count = build_diagnostic(
        queries, profiles, query_ids, profile_ids, projection)
    return {
        'runs': runs,
        'audits': audits,
        'diagnostic': {
            'equivalence': equivalence,
            'basis': basis,
            'cost': cost,
            'count': count,
        },
    }


def build_diagnostic(queries, profiles, query_ids, profile_ids, projection):
    signatures = {}
    for pid in profile_ids:
        signature = tuple(projection[(qid, pid)] for qid in query_ids)
        signatures.setdefault(signature, []).append(pid)
    equivalence = sorted(sorted(members) for members in signatures.values())

    requirements = []
    for index, first in enumerate(profile_ids):
        for second in profile_ids[index + 1:]:
            different = frozenset(
                qid for qid in query_ids
                if projection[(qid, first)] != projection[(qid, second)])
            if different and different not in requirements:
                requirements.append(different)
    if not requirements:
        return equivalence, [], 0, 0

    total = len(requirements)
    useful = []
    for qid in query_ids:
        mask = 0
        for position, required in enumerate(requirements):
            if qid in required:
                mask |= 1 << position
        if mask:
            useful.append((mask, queries[qid].cost, qid))

    # A query is never needed when a no-more-expensive query covers a
    # superset of the pairs it distinguishes.
    useful.sort(key=lambda item: (item[1], item[2]))
    candidates = []
    for mask, cost, qid in useful:
        if not any(mask & ~kept[0] == 0 for kept in candidates):
            candidates.append((mask, cost, qid))

    best = minimum_basis(candidates, total)
    basis = sorted(candidates[index][2]
                   for index in range(len(candidates)) if best >> index & 1)
    cost = sum(queries[qid].cost for qid in basis)
    return equivalence, basis, cost, len(basis)


def minimum_basis(candidates, total):
    """Exact optimum: least total cost, then fewest queries.

    ``total`` requirements are encoded as bits; a query is a mask over them
    and a basis must cover every bit.  The exhaustive subset dynamic program
    is bounded by 2**20 states because at most 20 queries exist.
    """
    full = (1 << total) - 1
    masks = [item[0] for item in candidates]
    costs = [item[1] for item in candidates]
    size = 1 << len(candidates)
    covered = [0] * size
    spent = [0] * size
    best_cost = 0
    best_count = 0
    best_mask = 0
    found = False
    for subset in range(1, size):
        low = subset & -subset
        index = low.bit_length() - 1
        previous = subset ^ low
        mask = covered[previous] | masks[index]
        covered[subset] = mask
        cost = spent[previous] + costs[index]
        spent[subset] = cost
        if mask == full:
            count = subset.bit_count()
            if (not found or cost < best_cost or
                    (cost == best_cost and
                     (count < best_count or
                      (count == best_count and subset < best_mask)))):
                found = True
                best_cost = cost
                best_count = count
                best_mask = subset
    return best_mask


# ------------------------------------------------------------------ driver --

def emit(text):
    sys.stdout.write(text)
    sys.stdout.flush()


def main():
    try:
        raw = sys.stdin.buffer.read(INPUT_LIMIT + 1)
    except Exception:
        emit(_ERROR)
        return
    if len(raw) > INPUT_LIMIT:
        emit(_ERROR)
        return
    try:
        document = load_document(raw)
        result = analyze(document)
    except Invalid:
        emit(_ERROR)
        return
    except Exception:
        emit(_ERROR)
        return
    emit(json.dumps(result, separators=(',', ':'), ensure_ascii=True))
    emit('\n')


if __name__ == '__main__':
    main()
